return $input.all().map((item, index) => {
  const lead = item.json;
  const priority = lead.adminPain === 'slow-lead-response' ? 'high' : 'normal';
  return {
    json: {
      taskId: `CALLBACK-${lead.leadId}`,
      priority,
      dueInMinutes: priority === 'high' ? 2 : 15,
      contactName: lead.contactName,
      workPhone: lead.workPhone,
      practiceName: lead.practiceName,
      callbackScript: 'Call back about the practice automation audit. Keep questions limited to practice operations, availability for a discovery call, and current admin workflow. Do not ask for patient details, symptoms, diagnosis, insurance member IDs, or clinical notes.',
      source: lead.source,
      createdFromLead: lead.leadId,
      demoOnly: true,
      sortOrder: index + 1
    }
  };
});
